</ResponseField>

<ResponseField name="progress" type="integer">
  Porcentaje de progreso (0-100).
</ResponseField>

<ResponseField name="audio_url" type="string">
  Enlace de descarga del archivo de audio (cuando se completa).
</ResponseField>

<ResponseField name="video_url" type="string">
  Enlace a la versión en video con efectos de visualización (cuando se completa).
</ResponseField>

<ResponseField name="title" type="string">
  Título de la canción generada.
</ResponseField>

<ResponseField name="lyrics" type="string">
  Letra generada o proporcionada.
</ResponseField>

<ResponseField name="error" type="string">
  Mensaje de error (en caso de fallo).
